ruleExplore.name:
@js:
var node = result;
var links = node.select("a.s.xst,a[href*=thread-],a[href*=viewthread]");
var title = "";
for (var i = 0; i < links.size(); i++) {
    var text = String(links.get(i).text()).replace(/\s+/g, " ").trim();
    if (text && !/^\d+$/.test(text) && !/^(New|下一页|返回|只看)/i.test(text)) { title = text; break; }
}
title;

